const fs = require('fs');

function getSubjectKnowledge(slug, title) {
  const normSlug = slug.toLowerCase();
  const normTitle = title.toLowerCase();

  let banglaName = title.split('(')[0].replace(/বিভাগ|অনুষদ|ইনস্টিটিউট|Subject Review|রিভিউ|পূর্ণাঙ্গ/gi, '').trim();
  if (!banglaName) {
    banglaName = title.split('Subject Review')[0].trim();
  }

  let institutionMention = '';
  if (normSlug.includes('-cu') || normTitle.includes('cu') || normTitle.includes('চট্টগ্রাম')) institutionMention = 'চট্টগ্রাম বিশ্ববিদ্যালয় (CU)';
  else if (normSlug.includes('-ruet') || normTitle.includes('ruet') || normTitle.includes('রুয়েট')) institutionMention = 'রাজশাহী প্রকৌশল ও প্রযুক্তি বিশ্ববিদ্যালয় (RUET)';
  else if (normSlug.includes('-kuet') || normTitle.includes('kuet') || normTitle.includes('কুয়েট')) institutionMention = 'খুলনা প্রকৌশল ও প্রযুক্তি বিশ্ববিদ্যালয় (KUET)';
  else if (normSlug.includes('-cuet') || normTitle.includes('cuet') || normTitle.includes('চুয়েট')) institutionMention = 'চট্টগ্রাম প্রকৌশল ও প্রযুক্তি বিশ্ববিদ্যালয় (CUET)';
  else if (normSlug.includes('-sust') || normTitle.includes('sust') || normTitle.includes('শাবিপ্রবি')) institutionMention = 'শাহজালাল বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয় (SUST)';
  else if (normSlug.includes('-du') || normTitle.includes('du') || normTitle.includes('ঢাকা বিশ্ববিদ্যালয়')) institutionMention = 'ঢাকা বিশ্ববিদ্যালয় (DU)';
  else if (normSlug.includes('-bau') || normTitle.includes('bau') || normTitle.includes('বাকৃবি')) institutionMention = 'বাংলাদেশ কৃষি বিশ্ববিদ্যালয় (BAU)';
  else if (normSlug.includes('-butex') || normTitle.includes('butex') || normTitle.includes('বুটেক্স')) institutionMention = 'বাংলাদেশ টেক্সটাইল বিশ্ববিদ্যালয় (BUTEX)';
  else if (normSlug.includes('-bsmrmu') || normTitle.includes('bsmrmu')) institutionMention = 'বঙ্গবন্ধু শেখ মুজিবুর রহমান মেরিটাইম ইউনিভার্সিটি (BSMRMU)';
  else if (normSlug.includes('-bup') || normTitle.includes('bup')) institutionMention = 'বাংলাদেশ ইউনিভার্সিটি অব প্রফেশনালস (BUP)';
  else if (normSlug.includes('-mist') || normTitle.includes('mist')) institutionMention = 'মিলিটারি ইনস্টিটিউট অব সায়েন্স অ্যান্ড টেকনোলজি (MIST)';
  else if (normSlug.includes('-nstu') || normTitle.includes('nstu')) institutionMention = 'নোয়াখালী বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয় (NSTU)';
  else if (normSlug.includes('-mbstu') || normTitle.includes('mbstu')) institutionMention = 'মাওলানা ভাসানী বিজ্ঞান ও প্রযুক্তি বিশ্ববিদ্যালয় (MBSTU)';

  const domain = detectDomain(normSlug, normTitle);
  return generateKnowledgeForDomain(domain, banglaName, title, institutionMention, normSlug);
}

function detectDomain(slug, title) {
  const text = slug + ' ' + title;

  if (/(?:cse|computer|software|swe|iit|information-and-communication|cyber|data-science|artificial-intelligence|urban-informatics)/i.test(text)) return 'cse';
  if (/(?:eee|ete|ece|telecommunication|electrical|electronic|semiconductor|renewable-energy)/i.test(text)) return 'eee';
  if (/(?:mechanical|me-|mechatronics|mte|aerospace|aeronautical|robotics|autonomous|automobile|ipe|iem|industrial-and-production)/i.test(text)) return 'me';
  if (/(?:civil|cee|becm|architecture|urp|urban|environmental-science-engineering|building-engineering)/i.test(text)) return 'civil';
  if (/(?:chemical|acce|materials|mse|glass|gce|petroleum|pme|leather|le-|applied-chemistry)/i.test(text)) return 'chemical';
  if (/(?:textile|butex|yarn|fabric|wet-process|apparel|tem|tmd|dyes)/i.test(text)) return 'textile';
  if (/(?:microbiology|genetic|geb|biotechnology|biochemistry|bmb|pharmacy|medical|mbbs|dental|bds|biomedical|bme|synthetic-biology|astrobiology)/i.test(text)) return 'bio';
  if (/(?:agriculture|agri|animal-husbandry|veterinary|dvm|fisheries|forestry|soil|crop|agronomy|horticulture)/i.test(text)) return 'agri';
  if (/(?:physics|chemistry|math|mathematics|statistics|stat|geology|oceanography|marine-science|actuarial|disaster)/i.test(text)) return 'science';
  if (/(?:accounting|finance|marketing|management|banking|hrm|business|economics|bba|tourism)/i.test(text)) return 'business';
  if (/(?:law|maritime-law|space-law|criminology)/i.test(text)) return 'law';
  if (/(?:sociology|anthropology|public-administration|pad|political-science|international-relation|journalism|psychology|peace|gender|social-work|ier|education)/i.test(text)) return 'social';
  if (/(?:english|bangla|bengali|farsi|philosophy|history|islamic|fine-art|linguistics)/i.test(text)) return 'arts';

  return 'general_stem';
}

function generateKnowledgeForDomain(domain, name, fullTitle, institution, slug) {
  const targetInst = institution ? `বিশেষ করে ${institution}-সহ` : 'বাংলাদেশের শীর্ষ পাবলিক ও প্রকৌশল বিশ্ববিদ্যালয়গুলোতে';

  switch (domain) {
    case 'cse': return getCseDomainKnowledge(name, fullTitle, targetInst);
    case 'eee': return getEeeDomainKnowledge(name, fullTitle, targetInst);
    case 'me': return getMeDomainKnowledge(name, fullTitle, targetInst);
    case 'civil': return getCivilDomainKnowledge(name, fullTitle, targetInst);
    case 'chemical': return getChemicalDomainKnowledge(name, fullTitle, targetInst);
    case 'textile': return getTextileDomainKnowledge(name, fullTitle, targetInst);
    case 'bio': return getBioDomainKnowledge(name, fullTitle, targetInst);
    case 'agri': return getAgriDomainKnowledge(name, fullTitle, targetInst);
    case 'science': return getScienceDomainKnowledge(name, fullTitle, targetInst);
    case 'business': return getBusinessDomainKnowledge(name, fullTitle, targetInst);
    case 'law': return getLawDomainKnowledge(name, fullTitle, targetInst);
    case 'social': return getSocialDomainKnowledge(name, fullTitle, targetInst);
    case 'arts': return getArtsDomainKnowledge(name, fullTitle, targetInst);
    default: return getCseDomainKnowledge(name, fullTitle, targetInst);
  }
}

